        $limits=array('source_key'=>120,'exam_attempt'=>80,'mtp_series'=>40,'section'=>120,'reference'=>40,'subreference'=>40,'title'=>190,'scheme'=>190,'law_context'=>2000,'question_page'=>80,'reasoning'=>6000,'confidence'=>80,'review_notes'=>10000,'rights_mode'=>32,'rights_basis'=>4000,'review_question_text'=>100000,'review_answer_text'=>100000,'extraction_status'=>80,'source_revision'=>190,'question_type'=>24,'issue_period'=>190);
        foreach($limits as $k=>$limit){$value=$data[$k]??'';if(!is_string($value)||strlen($value)>$limit||preg_match('~(?:drive|docs)\.google\.com~i',html_entity_decode(rawurldecode($value),ENT_QUOTES|ENT_HTML5,'UTF-8')))return CAFCC_Repository::error('Invalid '.$k.'; private links and silently truncated text are not allowed.');$data[$k]=sanitize_textarea_field($value);}
