        $answer=$data['answer']??array();if(!is_array($answer)||array_diff(array_keys($answer),array('source_hash','official_url','reference','subreference','page','coordinates','question_identity','question_reference','question_subreference','notes','answer_ids','mode','question_source_hash','subject_code','source_type','exam_attempt','mtp_series','issue_period','scheme','source_revision','alternative','parent_reference')))return CAFCC_Repository::error('Invalid answer mapping fields.');
