        $format=CAFCC_Release_V5::format($data);if(isset($data['question_format'])&&!in_array(strtolower($data['question_format']),array('subjective','mcq','mixed'),true))return CAFCC_Repository::error('Choose SUBJECTIVE, MCQ or MIXED.');$data['question_format']=$format;
        $data['rights_grant_id']=CAFCC_Repository::id($data['rights_grant_id']??null,true);if(is_wp_error($data['rights_grant_id']))return $data['rights_grant_id'];
