    private static function columns($data){return array('pilot_gate'=>CAFCC_Review_Tools::pilot($data)?1:0,'manual_quality_pass'=>CAFCC_Review_Tools::comparison_valid($data)?1:0,'permission_required'=>($data['rights_mode']??'')==='licensed_public'?1:0,'question_format'=>CAFCC_Release_V5::format($data),'stable_id'=>$data['stable_id'],'source_hash'=>$data['source_hash'],'source_identity'=>hash('sha256',implode('|',array($data['source_hash'],$data['section'],$data['reference'],$data['subreference']))),'source_key'=>$data['source_key'],'subject_code'=>$data['subject_code'],'source_type'=>$data['source_type'],'exam_attempt'=>$data['exam_attempt'],'mtp_series'=>$data['mtp_series'],'section_label'=>$data['section'],'question_number'=>$data['reference'],'subquestion_number'=>$data['subreference'],'payload'=>wp_json_encode($data),'payload_hash'=>hash('sha256',wp_json_encode($data)),'modified_at'=>current_time('mysql',true));}
    public static function import_preview($input){
        if(is_wp_error($e=self::admin()))return $e;$rows=$input['records']??null;$key=$input['batch_key']??'';
        if(!is_string($key)||!preg_match('/^[A-Za-z0-9_.:-]{2,120}$/D',$key)||!is_array($rows)||!array_is_list($rows)||!count($rows)||count($rows)>100)return CAFCC_Repository::error('Use a named batch of 1–100 records.');
        $clean=array();$errors=array();$seen=array();$retained=array();$conflict_records=array();$skip_existing=$input['skip_existing']??false;if(!is_bool($skip_existing))return CAFCC_Repository::error('Skip-existing must be true or false.');global $wpdb;$t=self::table();
        foreach($rows as $i=>$r){$v=self::clean($r);if(is_wp_error($v)){$errors[]=array('row'=>$i+1,'message'=>$v->get_error_message());continue;}if(isset($seen[$v['stable_id']])){$errors[]=array('row'=>$i+1,'message'=>'Duplicate stable identity in batch.');continue;}$source_identity=hash('sha256',implode('|',array($v['source_hash'],$v['section'],$v['reference'],$v['subreference'])));if(isset($seen['source-'.$source_identity])){$errors[]=array('row'=>$i+1,'message'=>'Duplicate appearance with a different candidate ID.');continue;}$seen['source-'.$source_identity]=true;$seen[$v['stable_id']]=true;$old=$wpdb->get_row($wpdb->prepare("SELECT id,revision,payload_hash FROM $t WHERE stable_id=%s OR source_identity=%s",$v['stable_id'],hash('sha256',implode('|',array($v['source_hash'],$v['section'],$v['reference'],$v['subreference'])))),ARRAY_A);$hash=hash('sha256',wp_json_encode($v));if($old&&$old['payload_hash']!==$hash){$conflict_records[]=array('id'=>(int)$old['id'],'expected_revision'=>(int)$old['revision'],'record'=>$v);if($skip_existing){$retained[]=$v['stable_id'];continue;}}$clean[]=array('data'=>$v,'existing_id'=>$old['id']??null,'duplicate'=>$old&&$old['payload_hash']===$hash,'conflict'=>$old&&$old['payload_hash']!==$hash);}
        $token=wp_generate_uuid4();set_transient('cafcc_bank_preview_'.$token,array('owner'=>get_current_user_id(),'batch_key'=>$key,'rows'=>$clean,'expires'=>time()+1800,'can_apply'=>!$errors&&!count(array_filter($clean,function($r){return $r['conflict'];}))),1800);
        return array('retained_existing'=>$retained,'conflict_records'=>$conflict_records,'token'=>$token,'records'=>count($clean),'errors'=>$errors,'duplicates'=>count(array_filter($clean,function($r){return $r['duplicate'];})),'conflicts'=>count(array_filter($clean,function($r){return $r['conflict'];})),'can_apply'=>!$errors&&!count(array_filter($clean,function($r){return $r['conflict'];})));
    }
    public static function import_apply($token){
        if(is_wp_error($e=self::admin()))return $e;if(!is_string($token)||!preg_match('/^[a-f0-9-]{36}$/D',$token))return CAFCC_Repository::error('Invalid preview token.');$preview=get_transient('cafcc_bank_preview_'.$token);if(!$preview||empty($preview['can_apply'])||$preview['owner']!==get_current_user_id()||$preview['expires']<time())return CAFCC_Repository::error('Preview expired or belongs to another administrator.',409);
        return CAFCC_Academic::transaction(function()use($preview,$token){global $wpdb;$t=self::table();$added=0;$skipped=0;
            foreach($preview['rows'] as $r){$v=$r['data'];$row=self::columns($v);$old=$wpdb->get_row($wpdb->prepare("SELECT * FROM $t WHERE stable_id=%s FOR UPDATE",$v['stable_id']),ARRAY_A);
                if($old){if($old['payload_hash']!==$row['payload_hash'])return CAFCC_Repository::error('Existing correction differs. Reprocessing cannot overwrite it; review conflict.',409);$skipped++;continue;}
                $row=array_merge($row,array('revision'=>1,'status'=>'needs_review','publication_status'=>'draft','approvals'=>'{}','batch_key'=>$preview['batch_key']));if(false===$wpdb->insert($t,$row))return CAFCC_Repository::error('Cannot import draft candidate.',409);$id=$wpdb->insert_id;if(!self::audit(self::get($id),'import_draft'))return CAFCC_Repository::error('Cannot retain audit.',500);$added++;
            }
            $bt=CAFCC_Bank_DB::table('batches');$wpdb->query($wpdb->prepare("INSERT IGNORE INTO $bt (batch_key,owner_id,batch_type,status,manifest,created_at) VALUES(%s,%d,'research','drafts_imported',%s,%s)",$preview['batch_key'],get_current_user_id(),wp_json_encode(array('rows'=>count($preview['rows']))),current_time('mysql',true)));
            delete_transient('cafcc_bank_preview_'.$token);return array('added'=>$added,'skipped_identical'=>$skipped,'publication_status'=>'draft');
        });
    }
    public static function save($id,$input){
        if(is_wp_error($e=self::admin()))return $e;if(!is_array($input)||array_diff(array_keys($input),array('expected_revision','data')))return CAFCC_Repository::error('Unexpected review edit.');
        return CAFCC_Academic::transaction(function()use($id,$input){global $wpdb;$old=self::get($id,true);if(!$old)return CAFCC_Repository::error('Review not found.',404);if((string)($input['expected_revision']??'')!==(string)$old['revision'])return CAFCC_Repository::error('Stale review revision. Reload before editing.',409);
            $data=self::clean($input['data']??array());if(is_wp_error($data))return $data;if(wp_json_encode($data['ai_proposal'])!==wp_json_encode($old['data']['ai_proposal']??array()))return CAFCC_Repository::error('Original AI proposal is retained as immutable evidence; edit corrected tags/reasoning instead.',409);
            foreach(array('stable_id','source_hash','source_key','subject_code','source_type','section','reference','subreference') as $k){if((string)$data[$k] !== (string)$old['data'][$k])return CAFCC_Repository::error('Source/question identity is immutable. Hold this record and import a corrected source revision.',409);}
            foreach(array('exam_attempt','mtp_series') as $k){if((string)$data[$k] !== (string)$old['data'][$k]&&!empty($old['question_id']))return CAFCC_Repository::error('A prepared question/source identity cannot be reassigned. Hold it and review an explicit source revision; IDs and student history are retained.',409);}
            $approvals=$old['approval_state'];$changed=array();foreach(self::STAGES as $stage){if(self::fingerprint($old,$stage)!==self::fingerprint(array_merge($old,array('data'=>$data)),$stage))$changed[]=$stage;}
            if(in_array('source',$changed,true))$changed=self::STAGES;
            if(in_array('boundary',$changed,true))$changed=array_unique(array_merge($changed,array('classification','answer_mapping','question_revision','answer_revision')));
            if(in_array('answer_mapping',$changed,true))$changed[]='answer_revision';
            if(in_array('rights',$changed,true))$changed=array_merge($changed,array('question_revision','answer_revision'));
            foreach($changed as $stage)unset($approvals[$stage]);unset($approvals['publication']);
            $row=array_merge(self::columns($data),array('revision'=>(int)$old['revision']+1,'approvals'=>wp_json_encode($approvals),'status'=>'needs_review','publication_status'=>'draft'));
            if(false===$wpdb->update(self::table(),$row,array('id'=>$id))||!self::audit(self::get($id),'saved_draft'))return CAFCC_Repository::error('Cannot retain review revision.',500);return self::get($id);
        });
    }
    public static function content_version($row,$kind){global $wpdb;if(empty($row['question_id']))return array('reference_only');$t=CAFCC_Practice::table('content');$r=$wpdb->get_row($wpdb->prepare("SELECT id,revision,approved_revision,approved_by,author_name,SHA2(body_html,256) AS body_sha256,rights_type,rights_basis,rights_expires,review_status,publication_status FROM $t WHERE question_id=%d AND content_kind=%s",$row['question_id'],$kind),ARRAY_A);return $r?:array('reference_only');}
    public static function fingerprint($row,$stage){
        $d=$row['data'];$sets=array('source'=>array('source_hash','source_key','title','subject_code','source_type','exam_attempt','mtp_series','official_url','scheme','edition_id','law_context','source_revision','issue_period'),'boundary'=>array('section','reference','subreference','question_page','question_coordinates','heading_evidence','marks','marks_verified','question_format','practice_structure','quality_checks'),'classification'=>array('edition_id','classification','reasoning'),'answer_mapping'=>array('answer'),'rights'=>array('rights_mode','rights_basis','rights_grant_id'));
        $v=in_array($stage,array('question_revision','answer_revision'),true)?self::content_version($row,'question_revision'===$stage?'question':'answer'):array_intersect_key($d,array_flip($sets[$stage]??array()));return hash('sha256',wp_json_encode($v));
    }
    private static function edition_applies($data){
        $ed=CAFCC_Academic::get('editions',$data['edition_id']);if(!$ed||!CAFCC_Academic::row_published($ed))return false;
        $normalise=function($v){return strtolower(preg_replace('/[^a-z0-9]+/i','',$v));};$attempt=$normalise($data['exam_attempt']);
        $bundle=json_decode(file_get_contents(dirname(__DIR__).'/data/taxonomy-v04-proposals.json'),true);$rule=$bundle['attempt_rules'][$ed['edition_key']]??null;
        if($rule){if(isset($rule['attempts']))return in_array($attempt,array_map($normalise,$rule['attempts']),true);if(isset($rule['from'])&&preg_match('/^(January|February|March|April|May|June|July|August|September|October|November|December)\s+([12][0-9]{3})$/i',trim($data['exam_attempt']),$m)){$date=gmdate('Y-m',strtotime('1 '.$m[1].' '.$m[2].' UTC'));return $date>=$rule['from']&&(!isset($rule['until'])||$date<=$rule['until']);}return false;}
        return $attempt!==''&&str_contains($normalise($ed['applicability']),$attempt);
    }
    public static function stage_valid($row,$stage){
        $d=$row['data'];
        if('source'===$stage&&$d['source_type']==='exam'&&(preg_match('/^May\s+2020$/i',$d['exam_attempt'])||(preg_match('/^[A-Za-z]+\s+20\d{2}$/D',$d['exam_attempt'])&&strtotime('1 '.$d['exam_attempt'].' UTC')>time())))return 'An actual examination source cannot be the cancelled May 2020 paper or a future examination. Keep real RTP/MTP preparation contexts separate.';
        if('source'===$stage&&(!$d['official_url']||!$d['scheme']||!$d['edition_id']||in_array($d['subject_code'],array('DT','IDT'),true)&&!$d['law_context']))return 'Verify official source, scheme, historical edition and tax applicability.';
        if('source'===$stage&&$d['source_type']!=='other'&&!self::edition_applies($d))return 'The source attempt is outside the sourced edition applicability, or the edition has not been reviewed. Select/review the correct historical edition; no automatic May 2026 mapping is allowed.';
