    }
    public static function detail($id){
        if(is_wp_error($e=self::admin()))return $e;$r=self::get($id);if(!$r)return CAFCC_Repository::error('Review not found.',404);$r['readiness']=self::readiness($r);$r['owner_blockers']=CAFCC_Release_V5::blockers($r);$r['publication_checklist']=CAFCC_Review_Tools::checklist($r);$r['shared_scenario']=!empty($r['data']['practice_structure']['scenario_key'])?CAFCC_Review_Tools::scenario($r['data']['source_hash'],$r['data']['practice_structure']['scenario_key']):null;$r['practice_preview']=array();if($r['question_id']){global $wpdb;$t=CAFCC_Practice::table('content');$rows=$wpdb->get_results($wpdb->prepare("SELECT * FROM $t WHERE question_id=%d AND rights_type IN ('original','licensed') AND rights_basis<>'' AND author_name<>''",$r['question_id']),ARRAY_A);foreach($rows as $pc)$r['practice_preview'][$pc['content_kind']]=array('body_html'=>CAFCC_Practice::html($pc['body_html']),'mcq_options'=>json_decode($pc['options_json'],true),'author'=>$pc['author_name'],'rights_type'=>$pc['rights_type'],'revision'=>$pc['revision'],'review_status'=>$pc['review_status']);}return $r;
    }
    public static function listing($r){
        global $wpdb;$page=$r->get_param('page')??1;$search=$r->get_param('search')??'';$status=$r->get_param('status')??'';$sort=$r->get_param('sort')??'id';$direction=$r->get_param('direction')??'DESC';$subject=$r->get_param('subject')??'';
        if(!is_scalar($page)||!preg_match('/^[1-9][0-9]{0,4}$/D',(string)$page)||!is_string($search)||strlen($search)>120||!in_array($sort,array('id','subject_code','source_type','exam_attempt','status','modified_at'),true)||!in_array($direction,array('ASC','DESC'),true)||!is_string($status)||!is_string($subject))return CAFCC_Repository::error('Invalid table filter.');
        $where='1=1';$args=array();$before=$r->get_param('before_id');if($before){$before=CAFCC_Repository::id($before);if(is_wp_error($before))return $before;$where.=' AND id<%d';$args[]=$before;}$format=$r->get_param('question_format');if($format){if(!in_array($format,array('subjective','mcq','mixed'),true))return CAFCC_Repository::error('Invalid question format.');$where.=' AND question_format=%s';$args[]=$format;}$after=$r->get_param('after_id');if($after){$after=CAFCC_Repository::id($after);if(is_wp_error($after))return $after;$where.=' AND id>%d';$args[]=$after;}foreach(array('status'=>$status,'subject_code'=>$subject) as $k=>$v){if($v){$where.=" AND $k=%s";$args[]=$v;}}if($search){$where.=' AND (stable_id LIKE %s OR question_number LIKE %s OR exam_attempt LIKE %s OR payload LIKE %s)';$like='%'.$wpdb->esc_like($search).'%';array_push($args,$like,$like,$like,$like);}
        $t=self::table();$count=(int)$wpdb->get_var($args?$wpdb->prepare("SELECT COUNT(*) FROM $t WHERE $where",$args):"SELECT COUNT(*) FROM $t WHERE $where");$sql="SELECT id FROM $t WHERE $where ORDER BY $sort $direction LIMIT 50 OFFSET %d";$args[]=((int)$page-1)*50;$ids=$wpdb->get_col($wpdb->prepare($sql,$args));return array('items'=>array_map(function($id){$r=self::get($id);$r['has_private_preview']=!empty($r['data']['rich_content'])||!empty($r['data']['review_question_text'])||!empty($r['data']['review_answer_text']);unset($r['data']['review_question_text'],$r['data']['review_answer_text'],$r['data']['previous_corrections'],$r['data']['rich_content']);return $r;},$ids),'total'=>$count,'per_page'=>50,'page'=>(int)$page);
    }
    public static function body($r,$limit=2000000){if(strlen($r->get_body())>$limit)return CAFCC_Repository::error('Use a batch smaller than 2 MB.',413);$v=$r->get_json_params();return is_array($v)&&!array_is_list($v)?$v:CAFCC_Repository::error('Send a JSON object.');}
    public static function adopt($occid,$input){
        if(is_wp_error($e=self::admin()))return $e;$occ=CAFCC_Academic::get('occurrences',$occid);if(!$occ)return CAFCC_Repository::error('Choose an existing connected occurrence. Legacy references must first be connected through the retained academic manager.');
        global $wpdb;$t=self::table();if($wpdb->get_var($wpdb->prepare("SELECT id FROM $t WHERE occurrence_id=%d",$occid)))return CAFCC_Repository::error('Occurrence is already in review.',409);
        $q=CAFCC_Academic::get('questions',$occ['question_id']);$doc=CAFCC_Academic::get('documents',$occ['document_id']);$ed=CAFCC_Academic::get('editions',$occ['edition_id']);$sub=CAFCC_Repository::get('subjects',$ed['subject_id']);$tags=CAFCC_DB::table('question_tags');
        $d=array('stable_id'=>'EXISTING-O-'.$occid,'source_hash'=>$input['source_hash']??'','source_key'=>$doc['document_key'],'subject_code'=>$sub['code'],'source_type'=>$doc['source_type'],'exam_attempt'=>$doc['exam_attempt'],'mtp_series'=>$doc['mtp_series'],'section'=>$input['section']??'owner-identification-required','reference'=>$occ['question_number'],'subreference'=>$occ['subquestion_number'],'title'=>$doc['title'],'official_url'=>$doc['official_url'],'question_page'=>$occ['page_reference'],'edition_id'=>$occ['edition_id'],'classification'=>array_map('intval',$wpdb->get_col($wpdb->prepare("SELECT node_id FROM $tags WHERE question_id=%d",$q['id']))));
        $d=self::clean($d);if(is_wp_error($d))return $d;$values=self::columns($d);$values=array_merge($values,array('question_id'=>$q['id'],'occurrence_id'=>$occid,'approvals'=>'{}','status'=>'needs_review','publication_status'=>'draft','batch_key'=>'ADOPT-O-'.$occid));
        if(false===$wpdb->insert($t,$values))return CAFCC_Repository::error('Cannot prepare existing occurrence.',409);$r=self::get($wpdb->insert_id);return self::audit($r,'existing_v03_review')?$r:CAFCC_Repository::error('Cannot retain adoption history.',500);
    }
    public static function batch_active($alias){$b=CAFCC_Bank_DB::table('batches');return " AND NOT EXISTS(SELECT 1 FROM $b wb WHERE wb.batch_key=$alias.batch_key AND wb.status='withdrawn')";}
    public static function withdraw($key,$resume=false){
        if(is_wp_error($e=self::admin()))return $e;if(!is_string($key)||!preg_match('/^[A-Za-z0-9_.:-]{2,120}$/D',$key))return CAFCC_Repository::error('Invalid batch key.');
        return CAFCC_Academic::transaction(function()use($key,$resume){global $wpdb;$t=self::table();$b=CAFCC_Bank_DB::table('batches');$a=CAFCC_Bank_DB::table('audit');$count=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $t WHERE batch_key=%s",$key));if(!$count)return CAFCC_Repository::error('Batch not found.',404);$now=current_time('mysql',true);
            if(false===$wpdb->query($wpdb->prepare("INSERT INTO $b (batch_key,owner_id,batch_type,status,manifest,created_at) VALUES(%s,%d,'research',%s,'{}',%s) ON DUPLICATE KEY UPDATE status=VALUES(status)",$key,get_current_user_id(),$resume?'drafts_imported':'withdrawn',$now)))return CAFCC_Repository::error('Cannot update batch state.',500);
            $action=$resume?'batch_resumed_drafts':'batch_withdrawn';
            if(false===$wpdb->query($wpdb->prepare("INSERT INTO $a (review_id,revision,actor_id,action,snapshot,created_at) SELECT id,revision,%d,%s,JSON_OBJECT('stable_id',stable_id,'revision',revision,'status',status,'publication_status',publication_status,'payload',payload,'approvals',approvals),%s FROM $t WHERE batch_key=%s",get_current_user_id(),$action,$now,$key)))return CAFCC_Repository::error('Cannot retain batch history.',500);
            if(false===$wpdb->query($wpdb->prepare("UPDATE $t SET publication_status='draft',status=%s,revision=revision+1,approvals=JSON_REMOVE(approvals,'$.publication'),modified_at=%s WHERE batch_key=%s",$resume?'needs_review':'hold',$now,$key)))return CAFCC_Repository::error('Cannot withdraw batch safely.',500);
            return array('affected'=>$count,'status'=>$resume?'needs_review':'withdrawn','publication_status'=>'draft','retained'=>'All IDs, corrections, historical approvals and student records. Resuming never republishes.');
        });
    }
    public static function routes(){
        $admin=function($r){return CAFCC_REST::permission($r,true);};
        register_rest_route('cafcc/v4','/admin/master-history',array('methods'=>'GET','permission_callback'=>$admin,'callback'=>function($r){global $wpdb;$kind=$r->get_param('kind');$id=CAFCC_Repository::id($r->get_param('id'));if(!is_string($kind)||!preg_match('/^[a-z_]{2,40}$/D',$kind)||is_wp_error($id))return CAFCC_Repository::error('Choose a master entity and ID.');$t=CAFCC_Bank_DB::table('audit');return $wpdb->get_results($wpdb->prepare("SELECT * FROM $t WHERE review_id=0 AND JSON_UNQUOTE(JSON_EXTRACT(snapshot,'$.entity'))=%s AND JSON_UNQUOTE(JSON_EXTRACT(snapshot,'$.record_id'))=%s ORDER BY id DESC LIMIT 100",$kind,(string)$id),ARRAY_A);}));
        register_rest_route('cafcc/v4','/admin/reviews',array('methods'=>'GET','permission_callback'=>$admin,'callback'=>array(__CLASS__,'listing')));
        register_rest_route('cafcc/v4','/admin/reviews/(?P<id>[1-9][0-9]{0,17})',array(array('methods'=>'GET','permission_callback'=>$admin,'callback'=>function($r){return self::detail((int)$r['id']);}),array('methods'=>'PATCH','permission_callback'=>$admin,'callback'=>function($r){$d=self::body($r);return is_wp_error($d)?$d:self::save((int)$r['id'],$d);})));
        register_rest_route('cafcc/v4','/admin/reviews/(?P<id>[1-9][0-9]{0,17})/suggested-path',array('methods'=>'POST','permission_callback'=>$admin,'callback'=>function($r){$d=self::body($r);return is_wp_error($d)?$d:self::suggested_path((int)$r['id'],$d);}));
        register_rest_route('cafcc/v4','/admin/reviews/(?P<id>[1-9][0-9]{0,17})/prepare-reference',array('methods'=>'POST','permission_callback'=>$admin,'callback'=>function($r){$d=self::body($r);return is_wp_error($d)?$d:self::prepare((int)$r['id'],$d);}));
        register_rest_route('cafcc/v4','/admin/reviews/(?P<id>[1-9][0-9]{0,17})/decision',array('methods'=>'POST','permission_callback'=>$admin,'callback'=>function($r){$d=self::body($r);return is_wp_error($d)?$d:self::decision((int)$r['id'],$d);}));
        register_rest_route('cafcc/v4','/admin/reviews/(?P<id>[1-9][0-9]{0,17})/history',array('methods'=>'GET','permission_callback'=>$admin,'callback'=>function($r){global $wpdb;$t=CAFCC_Bank_DB::table('audit');return $wpdb->get_results($wpdb->prepare("SELECT * FROM $t WHERE review_id=%d ORDER BY id DESC LIMIT 100",$r['id']),ARRAY_A);}));
        register_rest_route('cafcc/v4','/admin/research/resume',array('methods'=>'POST','permission_callback'=>$admin,'callback'=>function($r){$d=self::body($r);return is_wp_error($d)?$d:self::withdraw($d['batch_key']??null,true);}));
        register_rest_route('cafcc/v4','/admin/research/withdraw',array('methods'=>'POST','permission_callback'=>$admin,'callback'=>function($r){$d=self::body($r);return is_wp_error($d)?$d:self::withdraw($d['batch_key']??null);}));
        register_rest_route('cafcc/v4','/admin/reviews/adopt/(?P<id>[1-9][0-9]{0,17})',array('methods'=>'POST','permission_callback'=>$admin,'callback'=>function($r){$d=self::body($r);return is_wp_error($d)?$d:self::adopt((int)$r['id'],$d);}));
        register_rest_route('cafcc/v4','/admin/taxonomy-search',array('methods'=>'GET','permission_callback'=>$admin,'callback'=>function($r){global $wpdb;$term=$r->get_param('term')??'';$edition=$r->get_param('edition_id');if(!is_string($term)||strlen($term)>120)return CAFCC_Repository::error('Invalid search.');$t=CAFCC_DB::table('taxonomy');$args=array('%'.$wpdb->esc_like($term).'%');$where='title LIKE %s';if($edition){$id=CAFCC_Repository::id($edition);if(is_wp_error($id))return $id;$where.=' AND edition_id=%d';$args[]=$id;}return array('items'=>$wpdb->get_results($wpdb->prepare("SELECT id,title,node_type,edition_id,heading_origin,review_status FROM $t WHERE $where ORDER BY position,id LIMIT 50",$args),ARRAY_A),'editions'=>CAFCC_Academic::listing('editions')['items']);}));
        foreach(array('preview','apply') as $action)register_rest_route('cafcc/v4','/admin/research/'.$action,array('methods'=>'POST','permission_callback'=>$admin,'callback'=>function($r)use($action){$d=self::body($r);return is_wp_error($d)?$d:('preview'===$action?self::import_preview($d):self::import_apply($d['token']??null));}));
    }
    public static function screen(){if(is_wp_error(self::admin()))wp_die('Administrator access required.');echo '<div class="wrap cafcc-studio" id="cafcc-studio"><header><span>ACADEMIC OPERATIONS · PRIVATE</span><h1>Question Review Studio</h1><p>Read the complete question and answer together. Choose Needs Review, Publish or Reject. Detailed approvals are retained internally. <a href="admin.php?page=cafcc-diagnostics">Getting started &amp; diagnostics</a></p><p>No rows yet? Import the private research JSON here. Installing the plugin does not import the offline question bank.</p></header><div class="studio-toolbar"><input type="search" id="studio-search" placeholder="Search ID, concept, attempt or evidence" aria-label="Search reviews"><select id="studio-status" aria-label="Review status"><option value="">All statuses</option><option>needs_review</option><option>hold</option><option>rejected</option><option>approved</option></select><select id="studio-sort" aria-label="Sort column"><option value="id">Newest record</option><option value="subject_code">Subject</option><option value="exam_attempt">Attempt</option><option value="modified_at">Modified</option></select><button id="studio-export" type="button">Download Review Excel</button><label>Upload decisions<input type="file" id="studio-excel" accept=".xlsx"></label><label>Import hierarchy / research JSON<input type="file" id="studio-import" accept=".json"></label></div><details><summary>Batch hold / resume</summary><label>Exact batch key <input id="studio-batch-key"></label><button type="button" id="studio-withdraw">Hold entire batch</button><button type="button" id="studio-resume">Resume as drafts</button><p>Both operations withdraw student publication. IDs, corrections and student records remain.</p></details><details><summary>Visible columns</summary><div id="studio-columns"></div></details><p id="studio-feedback" role="status" aria-live="polite"></p><div class="studio-scroll" tabindex="0" aria-label="Review table; scroll horizontally"><table><thead id="studio-head"></thead><tbody id="studio-rows"></tbody></table></div><nav id="studio-pages" aria-label="Review pages"></nav><dialog id="studio-panel" aria-label="Review question"><div id="studio-detail"></div></dialog><section id="studio-upload-preview" hidden></section></div>';}
